import random

def get_user_choice():
    """Get user's choice as either 'rock', 'paper', or 'scissors'."""
    while True:
        choice = input("Enter 'rock', 'paper', or 'scissors': ").lower()
        if choice in ['rock', 'paper', 'scissors']:
            return choice
        else:
            print("Invalid input. Please try again.")

def get_computer_choice():
    """Get computer's choice randomly between rock, paper, and scissors."""
    return random.choice(['rock', 'paper', 'scissors'])

def determine_winner(user_choice, computer_choice):
    """Determine the winner based on the game's rules."""
    if user_choice == computer_choice:
        return "It's a tie!"
    elif (user_choice == 'rock' and computer_choice == 'scissors') or \
         (user_choice == 'paper' and computer_choice == 'rock') or \
         (user_choice == 'scissors' and computer_choice == 'paper'):
        return f"You win! The computer chose {computer_choice}."
    else:
        return f"The computer wins! You chose {user_choice}."

if __name__ == "__main__":
    user_choice = get_user_choice()
    computer_choice = get_computer_choice()
    print(determine_winner(user_choice, computer_choice))
```

This program will run in an interactive loop, allowing the user to play multiple rounds of Rock, Paper, Scissors.
